import React, { useState } from 'react';
import FileUpload from './components/FileUpload';
import JobDescription from './components/JobDescription';
import Results from './components/Results';
import Header from './components/Header';
import { analyzeResume } from './utils/api';
import { FileText, Briefcase, TrendingUp } from 'lucide-react';

function App() {
  const [resumeFile, setResumeFile] = useState(null);
  const [jobDescription, setJobDescription] = useState('');
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [currentStep, setCurrentStep] = useState(1);

  const handleFileSelect = (file) => {
    setResumeFile(file);
    setError('');
    if (file && jobDescription) {
      setCurrentStep(3);
    } else if (file) {
      setCurrentStep(2);
    }
  };

  const handleJobDescriptionChange = (text) => {
    setJobDescription(text);
    setError('');
    if (text && resumeFile) {
      setCurrentStep(3);
    } else if (text) {
      setCurrentStep(2);
    }
  };

  const handleAnalyze = async () => {
    if (!resumeFile || !jobDescription.trim()) {
      setError('Please upload a resume and provide a job description');
      return;
    }

    setLoading(true);
    setError('');
    setResults(null);

    try {
      const result = await analyzeResume(resumeFile, jobDescription);
      setResults(result);
      setCurrentStep(4);
    } catch (err) {
      setError(err.message || 'An error occurred during analysis');
    } finally {
      setLoading(false);
    }
  };

  const handleReset = () => {
    setResumeFile(null);
    setJobDescription('');
    setResults(null);
    setError('');
    setLoading(false);
    setCurrentStep(1);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50">
      <Header />

      <main className="container mx-auto px-4 py-8 max-w-6xl">
        {/* Progress Steps */}
        <div className="mb-8">
          <div className="flex items-center justify-center space-x-4 md:space-x-8">
            <div className={`flex items-center ${currentStep >= 1 ? 'text-primary-600' : 'text-gray-400'}`}>
              <div className={`w-10 h-10 rounded-full flex items-center justify-center font-semibold ${
                currentStep >= 1 ? 'bg-primary-600 text-white' : 'bg-gray-200'
              }`}>
                1
              </div>
              <span className="ml-2 font-medium hidden md:inline">Upload Resume</span>
            </div>

            <div className={`w-8 md:w-16 h-1 ${currentStep >= 2 ? 'bg-primary-600' : 'bg-gray-300'}`} />

            <div className={`flex items-center ${currentStep >= 2 ? 'text-primary-600' : 'text-gray-400'}`}>
              <div className={`w-10 h-10 rounded-full flex items-center justify-center font-semibold ${
                currentStep >= 2 ? 'bg-primary-600 text-white' : 'bg-gray-200'
              }`}>
                2
              </div>
              <span className="ml-2 font-medium hidden md:inline">Job Description</span>
            </div>

            <div className={`w-8 md:w-16 h-1 ${currentStep >= 3 ? 'bg-primary-600' : 'bg-gray-300'}`} />

            <div className={`flex items-center ${currentStep >= 3 ? 'text-primary-600' : 'text-gray-400'}`}>
              <div className={`w-10 h-10 rounded-full flex items-center justify-center font-semibold ${
                currentStep >= 3 ? 'bg-primary-600 text-white' : 'bg-gray-200'
              }`}>
                3
              </div>
              <span className="ml-2 font-medium hidden md:inline">Analyze</span>
            </div>

            <div className={`w-8 md:w-16 h-1 ${currentStep >= 4 ? 'bg-primary-600' : 'bg-gray-300'}`} />

            <div className={`flex items-center ${currentStep >= 4 ? 'text-primary-600' : 'text-gray-400'}`}>
              <div className={`w-10 h-10 rounded-full flex items-center justify-center font-semibold ${
                currentStep >= 4 ? 'bg-primary-600 text-white' : 'bg-gray-200'
              }`}>
                4
              </div>
              <span className="ml-2 font-medium hidden md:inline">Results</span>
            </div>
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <div className="mb-6 p-4 bg-danger-50 border border-danger-200 rounded-lg text-danger-800 animate-slide-up">
            <p className="font-medium">Error: {error}</p>
          </div>
        )}

        {/* Main Content */}
        <div className="grid lg:grid-cols-2 gap-8">
          {/* Left Column - Input */}
          <div className="space-y-6">
            <FileUpload onFileSelect={handleFileSelect} selectedFile={resumeFile} />
            <JobDescription 
              value={jobDescription} 
              onChange={handleJobDescriptionChange} 
            />

            {/* Analyze Button */}
            <div className="flex justify-center">
              <button
                onClick={handleAnalyze}
                disabled={loading || !resumeFile || !jobDescription.trim()}
                className="btn-primary disabled:opacity-50 disabled:cursor-not-allowed px-8 py-3 text-lg font-semibold shadow-lg hover:shadow-xl transform hover:-translate-y-0.5 transition-all duration-200"
              >
                {loading ? (
                  <div className="flex items-center">
                    <div className="loading-spinner w-5 h-5 mr-2"></div>
                    Analyzing...
                  </div>
                ) : (
                  'Analyze Resume Match'
                )}
              </button>
            </div>

            {/* Reset Button */}
            {(resumeFile || jobDescription || results) && !loading && (
              <div className="flex justify-center">
                <button
                  onClick={handleReset}
                  className="btn-secondary"
                >
                  Start Over
                </button>
              </div>
            )}
          </div>

          {/* Right Column - Results */}
          <div>
            {results ? (
              <Results results={results} />
            ) : (
              <div className="card h-full flex items-center justify-center">
                <div className="text-center">
                  <TrendingUp className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                  <h3 className="text-xl font-semibold text-gray-600 mb-2">Ready to Analyze</h3>
                  <p className="text-gray-500">
                    Upload your resume and provide a job description to see your match score and detailed analysis.
                  </p>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Features Section */}
        {!results && (
          <div className="mt-16 grid md:grid-cols-3 gap-6">
            <div className="card text-center">
              <FileText className="w-12 h-12 text-primary-600 mx-auto mb-4" />
              <h3 className="font-semibold text-lg mb-2">Smart Text Extraction</h3>
              <p className="text-gray-600 text-sm">
                Automatically extracts and processes text from PDF and DOCX files
              </p>
            </div>

            <div className="card text-center">
              <Briefcase className="w-12 h-12 text-primary-600 mx-auto mb-4" />
              <h3 className="font-semibold text-lg mb-2">Skill Matching</h3>
              <p className="text-gray-600 text-sm">
                Identifies matched and missing skills based on job requirements
              </p>
            </div>

            <div className="card text-center">
              <TrendingUp className="w-12 h-12 text-primary-600 mx-auto mb-4" />
              <h3 className="font-semibold text-lg mb-2">AI-Powered Analysis</h3>
              <p className="text-gray-600 text-sm">
                Uses advanced NLP to calculate semantic similarity scores
              </p>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
